mapper.select:
select a.id as a_id, m.id as m_id, m.name as m_name, m.email as m_email, m.role as m_role, a.endpoint as a_endpoint, a.http_method as a_http_method, a.status_code as a_status_code, a.response_time_ms as a_response_time_ms, a.ip_address as a_ip_address, a.user_agent as a_user_agent, a.request_body as a_request_body, a.created_at as a_created_at FROM api_logs as a join members m on a.member_id = m.id WHERE 1 = 1
AND a.created_at >= #{from}
AND a.created_at <= #{to}
AND a.member_id = #{memberId}
ORDER BY a.created_at DESC;

select a.endpoint as a_endpoint, a.http_method as a_http_method, count(*) as a_count FROM api_logs as a WHERE 1 = 1
AND a.created_at >= #{from}
AND a.created_at <= #{to}
AND a.member_id = #{memberId}
GROUP BY a.endpoint, a.http_method Order BY a_count DESC

SELECT endpoint AS endpoint, http_method AS httpMethod, SUM(CASE WHEN status_code BETWEEN 200 AND 399 THEN 1 ELSE 0 END) AS successCount, SUM(CASE WHEN status_code >= 400 THEN 1 ELSE 0 END) AS failureCount, ROUND( SUM(CASE WHEN status_code BETWEEN 200 AND 299 THEN 1 ELSE 0 END) / COUNT(*) * 100, 2 ) AS successRate FROM api_logs WHERE 1 = 1
AND created_at >= #{from}
AND created_at <= #{to}
GROUP BY endpoint, http_method ORDER BY successRate DESC;

select endpoint as endpoint, http_method as httpMethod, ROUND(AVG(response_time_ms), 2) AS averageLatencyMs FROM api_logs WHERE 1 = 1
AND created_at >= #{from}
AND created_at <= #{to}
GROUP BY endpoint, http_method ORDER BY averageLatencyMs DESC
